from __future__ import annotations
PRIORITY = {'TCKN': 0, 'YKN': 0, 'PASSPORT': 1, 'FOREIGN_ID': 1, 'IBAN': 1, 'CREDIT_CARD': 2, 'VKN': 3, 'EMAIL': 4, 'ADDRESS': 5, 'PHONE': 6, 'PLATE': 7, 'PERSON': 8, 'BIRTH_DATE': 9, 'IP_ADDRESS': 10, 'HEALTH': 11, 'RELIGION': 11, 'POLITICAL': 11, 'UNION': 11, 'ETHNICITY': 11, 'SEXUAL_LIFE': 11, 'BIOMETRIC_GENETIC': 11, 'CRIMINAL_RECORD': 12}

FLAG_ONLY_DEFAULT = {'CRIMINAL_RECORD'}

def resolve_overlaps(results: list[RecognizerResult]) -> list[RecognizerResult]:
    ranked = sorted(results, key=lambda r: (PRIORITY.get(r.entity_type, 99), -r.score, -(r.end - r.start)))
    kept: list[RecognizerResult] = []
    for r in ranked:
        if all((r.end <= k.start or r.start >= k.end for k in kept)):
            kept.append(r)
    return sorted(kept, key=lambda r: r.start)

def _merge_adjacent(text: str, results: list[RecognizerResult]) -> list[RecognizerResult]:
    """Join same-type spans separated only by spaces ("depresyon" + "tedavisi")."""
    out: list[RecognizerResult] = []
    for r in results:
        if out and out[-1].entity_type == r.entity_type and (text[out[-1].end:r.start].strip(' \t') == '') and ('\n' not in text[out[-1].end:r.start]) and (r.start - out[-1].end <= 2):
            out[-1].end = r.end
            out[-1].score = max(out[-1].score, r.score)
        else:
            out.append(r)
    return out
